<?php
declare(strict_types=1);
namespace App\Models;
use App\Enums\ClassroomProgramType;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany,BelongsToMany};
class Classroom extends Model { protected $guarded=[]; protected $appends=['display_name']; protected function casts():array{return ['capacity'=>'integer','is_active'=>'boolean','program_type'=>ClassroomProgramType::class];} public function academicYear():BelongsTo{return $this->belongsTo(AcademicYear::class);} public function gradeLevel():BelongsTo{return $this->belongsTo(GradeLevel::class);} public function homeroomPersonnel():BelongsTo{return $this->belongsTo(Personnel::class,'homeroom_personnel_id');} public function memberships():HasMany{return $this->hasMany(ClassroomMembership::class);} public function activeMemberships():HasMany{return $this->memberships()->where('status','active');} public function students():BelongsToMany{return $this->belongsToMany(Student::class,'classroom_memberships')->withPivot(['status','joined_at','left_at'])->wherePivot('status','active');} public function createdBy():BelongsTo{return $this->belongsTo(User::class,'created_by');} public function updatedBy():BelongsTo{return $this->belongsTo(User::class,'updated_by');} public function getDisplayNameAttribute():string{$base=($this->gradeLevel?->name??'Kelas').' - '.$this->code;return filled($this->name)?$base.' ('.$this->name.')':$base;} public function getStudentCountAttribute():int{return $this->active_memberships_count??$this->activeMemberships()->count();} public function getCapacityLabelAttribute():string{return $this->capacity?$this->student_count.' / '.$this->capacity:(string)$this->student_count;} public function getIsOverCapacityAttribute():bool{return $this->capacity!==null&&$this->student_count>$this->capacity;} public function getHomeroomNameAttribute():string{return $this->homeroomPersonnel?->full_name??'Belum ada wali kelas';} }
